// ============================================================
// Portero de las recomendaciones: valida y frena el abuso ANTES
// de tocar la planilla. Publico == hostil hasta probar lo contrario.
// Las recomendaciones NUNCA se agregan solas a la biblioteca: quedan
// en la planilla para que alguien las revise a mano.
// ============================================================

const TOPE_DIARIO = 30;   // recomendaciones por dia en total
const LARGO_MAX_TITULO = 120;
const LARGO_MAX_AUTOR = 80;
const LARGO_MAX_COMENTARIO = 300;
const ORIGENES = [
  'https://obolfinance.com.ar',
  'https://obolfinance.github.io'
];

const entrada = $('Recibe la recomendación').item.json;
const crudo = entrada.body ?? entrada;
let d;
try {
  d = typeof crudo === 'string' ? JSON.parse(crudo) : crudo;
} catch (e) {
  d = {};
}

function rechazar(motivo) {
  return [{ json: { ok: false, motivo } }];
}

// Todo lo que va a la planilla: largo acotado y sin formulas. Sheets evalua
// como formula un texto que empieza con = + - @, y eso corre cuando alguien
// abre la planilla (por ejemplo, un IMPORTXML que se lleva otras filas).
function celda(v, max) {
  const s = String(v ?? '').trim().slice(0, max);
  return /^[=+\-@\t\r]/.test(s) ? "'" + s : s;
}

// 0. Turnstile: Cloudflare ya confirmo (o no) que esto lo mando un humano.
const ts = $('Verifica Turnstile').item.json;
// success solo dice que el token es valido para esta sitekey. hostname confirma
// que se emitio en nuestro sitio y no en otra pagina que use la misma clave.
const turnstileOk = ts.success === true && ts.hostname === 'obolfinance.com.ar';
if (!turnstileOk) return rechazar('bot');

// 1. Origen. No es seguridad real (se falsifica facil), pero filtra el ruido.
const headers = entrada.headers || {};
const origen = headers.origin || headers.referer || '';
if (ORIGENES.length && !ORIGENES.some(o => origen.startsWith(o))) {
  return rechazar('origen');
}

// 2. Tope diario global.
const estado = $getWorkflowStaticData('global');
const hoy = new Date().toISOString().slice(0, 10);
if (estado.dia !== hoy) { estado.dia = hoy; estado.cuenta = 0; }
if (estado.cuenta >= TOPE_DIARIO) return rechazar('limite');

// 3. Contenido
const titulo = celda(d.titulo, LARGO_MAX_TITULO);
const autor = celda(d.autor, LARGO_MAX_AUTOR);
const comentario = celda(d.comentario, LARGO_MAX_COMENTARIO);

const ok = titulo.length > 0;
if (ok) estado.cuenta = (estado.cuenta || 0) + 1;

return [{
  json: {
    ok,
    motivo: ok ? '' : 'falta_titulo',
    titulo,
    autor,
    comentario,
    pagina: celda(d.pagina, 200),
    fecha: new Date().toISOString(),
    agregado: 'NO'
  }
}];
